\bottomrule
\end{tabular}
\captionof{table}{Reinigungswasser beschaffen (Tab. 2.4)}
\end{center}
\end{konzept}

\section{Heilverlauf und Verbandswechsel}

\begin{konzept}{Konzept 2.3 – Heilverlauf und Verbandswechsel}
\textbf{Definition.} Eine gereinigte Wunde heilt in Phasen: Reinigung durch den Körper, Granulation (Wundgrund füllt sich), Epithelisierung (Haut schließt). Der Verbandswechsel folgt dem Zustand, nicht dem Kalender.

\textbf{Dreifache Prüfung:}
\begin{enumerate}
\item Erkennt man die Phasen ohne Gerät? Ja – an Farbe, Geruch und Feuchtigkeit.
\item Schadet zu häufiger Wechsel? Ja – jeder Abzug reißt junge Zellen ab.
\item Gilt das gleich für Stadt und Land? Ja.
\end{enumerate}

\textbf{Dreifache Bewertung:}
\begin{enumerate}
\item Einfachheit: hoch.
\item Folgenschwere: hoch – der Wechselrhythmus entscheidet über Heilung oder Fäulnis.
\item Übungsaufwand: mittel – Geruch und Farbe müssen gelernt sein (Anhang C, Monat 4).
\end{enumerate}

\textbf{Grenzen.} Eine Wunde, die nach 3 Tagen wärmer, röter, schmerzhafter wird oder nach faulem Geruch riecht, ist infiziert. Dann gilt Konzept 4.3 und jede erreichbare bessere Hilfe.

\textbf{Zustandstabelle Wunde (Tab. 2.5)}
\begin{center}
\begin{tabular}{lll}
\toprule
Befund & Bedeutung & Handlung \\
\midrule
Blassrosa Grund, leicht feucht & Granulation normal & Verband lassen, nach 2 Tagen wechseln \\
Gelber Belag, kein Geruch & Wundsekret normal & Spülen, dünnerer Verband \\
Grüner Belag, fauler Geruch & Infektion & Spülen, Honigauflage, Hilfe suchen \\
Schwarzer Rand, harte Kruste & Abgestorbenes Gewebe & Abtragen nur durch bessere Hilfe \\
Blutet beim Verbandwechsel stark & Tiefer Schaden & Zurückdrücken, Kompression, Hilfe \\
\bottomrule
\end{tabular}
\captionof{table}{Wundbefunde und Handlungen (Tab. 2.5)}
\end{center}

\textbf{Schritte: Verbandswechsel}
\begin{enumerate}
\item Wasche Hände, lege das neue Material bereit, ehe du den alten Verband öffnest.
\item Löse den Verband in Richtung des Haarwuchses; ziehe nicht über die Wunde, sondern ab.
\item Beurteile Grund, Rand, Geruch nach Tab. 2.5.
\item Spüle bei Bedarf mit abgekochtem Wasser.
\item Lege die neue Kompresse und binde in gleicher Technik wie zuvor.
\item Trage Uhrzeit, Befund und Maßnahme ins Protokoll (Vorlage A.1) ein.
\end{enumerate}

\begin{baustein}
\textbf{Merksätze zur Wunde.}
\begin{itemize}
\item Spülen statt schrubben: Wasser heilt, Reiben schadet.
\item Der erste Verband sitzt am besten – wechsle nur bei Bedarf.
\item Rötung, Wärme, Schmerz, Geruch: vier Zeichen, eins genügt zum Nachdenken, zwei zum Handeln.
\item Steckende Fremdkörper bleiben stecken.
\item Wasser, das man trinken kann, kann man in eine Wunde spülen – aber abgekocht ist besser.
\end{itemize}
\end{baustein}

\begin{stand}
\textbf{Arbeitsstand Wunde.}
\begin{checkliste}
\item Verbandkasten nach Tab. 2.3 vorhanden und ungeöffnet verpackt.
\item 20 Liter Wasser für Wundspülung abgekocht oder als Vorrat vorhanden.
\item Zwei Personen haben einen Übangswechsel am eigenen Kratzer geübt.
\end{checkliste}
\end{stand}

\section{Kapitel-Checkliste: Die Wunde}
\begin{checkliste}
