\chapter{Fieber und Infektion: das Feuer im Leib führen}

Fieber ist eine Abwehr, kein Feind. Die Gefahr beginnt, wenn es zu hoch steigt oder wenn sich eine Infektion ausbreitet, die der Körper nicht mehr allein bezwingt. Dieses Kapitel behandelt Messung, Führung des Fiebers und Erkennung der Wende zum Ernstfall.

\section{Fieber messen und führen}

\begin{konzept}{Konzept 4.1 – Fieber messen und führen}
\textbf{Definition.} Fieberführung heißt, Körpertemperatur und Kreislauf zu beobachten, Flüssigkeit zu ersetzen und das Fieber nur dann zu senken, wenn es den Körper schädigt.

\textbf{Dreifache Prüfung:}
\begin{enumerate}
\item Funktioniert es ohne Strom? Ja – Fieberthermometer gibt es als Galo-Gerät, als Streifen oder als reines Beobachtungsraster.
\item Schadet die Regel bei Befolgung nicht? Ja – sie senkt Fieber nicht vorschnell ab.
\item Gilt sie gleich in Stadt und Land? Ja.
\end{enumerate}

\textbf{Dreifache Bewertung:}
\begin{enumerate}
\item Einfachheit: hoch.
\item Folgenschwere: hoch – falsche Führung führt zu Austrocknung oder Krampfanfall.
\item Übungsaufwand: gering.
\end{enumerate}

\textbf{Grenzen.} Ohne Messung bleibt nur die Handprobe (Stirn, Nacken): Sie erkennt hohes Fieber, aber keine genauen Werte. Senke Fieber ohne Thermometer nicht aktiv, sondern sorge für Flüssigkeit und Wärmeabfuhr.

\textbf{Messraster (Tab. 4.1)}
\begin{center}
\begin{tabular}{lll}
\toprule
Temperatur (oral) & Bewertung & Maßnahme \\
\midrule
36,5 bis 37,5 °C & Normal & Keine \\
37,6 bis 38,5 °C & Erhöht & Beobachten, trinken, alle 2 h messen \\
38,6 bis 39,5 °C & Fieber & Bettruhe, 1 Tasse Flüssigkeit je Stunde, Waden nur lauwarm \\
39,6 bis 40,5 °C & Hohes Fieber & Arzt wenn erreichbar, Kühlung, keine kalten Bäder \\
Über 40,5 °C oder Krampf & Notfall & Sofort jede erreichbare Hilfe; kühlen an Leiste und Nacken \\
\bottomrule
\end{tabular}
\captionof{table}{Fieberstufen und Maßnahmen (Tab. 4.1)}
\end{center}

\textbf{Schritte: Fieber führen}
\begin{enumerate}
\item Lege den Kranken ins Bett, Decke nur bis zur Deckenmitte des Körpers.
\item Gib stündlich etwa 200 ml Flüssigkeit (Wasser, dünner Tee nach Tab. 3.5, Brühe).
\item Messe alle 2 Stunden und trage die Werte in das Fieberprotokoll (Vorlage A.2) ein.
\item Wechsle durchgeschwitzte Wäsche sofort; trockene Wärme danach.
\item Kühle erst ab 39,5 °C, und nur mit lauwarmem Wasser (30–32 °C) an Waden, Leiste, Nacken – kaltes Wasser schließt die Gefäße und treibt das Fieber.
\item Prüfe alle 4 Stunden Bewusstsein: Name, Ort, Datum nennen lassen.
\end{enumerate}

\begin{figure}[ht]
\centering
\includesvg[width=\textwidth]{illustrationen/abb-4-1}
\caption{Abb. 4.1 – Fieberkurve ablesen: wann beobachten, wann handeln}
\end{figure}

\section{Infektion erkennen}

\begin{konzept}{Konzept 4.2 – Infektion erkennen}
\textbf{Definition.} Eine Infektion ist das Eindringen und Vermehren von Keimen; örtlich zeigt sie sich als Entzündung, allgemein als Fieber, Schüttelfrost und raschem Puls.

\textbf{Dreifache Prüfung:}
\begin{enumerate}
\item Erkennt man die Zeichen ohne Labor? Ja – die fünf klassischen Entzündungszeichen sind sichtbar und tastbar.
\item Schadet die Regel bei Befolgung nicht? Nein.
\item Gilt sie gleich in Stadt und Land? Ja.
\end{enumerate}

\textbf{Dreifache Bewertung:}
\begin{enumerate}
\item Einfachheit: hoch.
\item Folgenschwere: hoch – die Wunde zur Blutvergiftung ist eine Frage von Stunden.
\item Übungsaufwand: gering.
\end{enumerate}

\textbf{Grenzen.} Ohne Antibiotika ist eine fortgeschrittene eitrige Infektion nicht behandelbar; jede erreichbare bessere Hilfe ist dann Pflicht. Rotgestreifte Lymphbahn (vom Herd zum Rumpf) heißt: Transport, sofort.

\textbf{Fünf Zeichen der Entzündung (Tab. 4.2)}
\begin{center}
\begin{tabular}{lll}
\toprule
Zeichen & Prüfung & Wo sichtbar \\
\midrule
Rötung & Vergleich mit gesunder Seite & Wundrand, Umkreis \\
Überwärmung & Handrückenprobe & Herd, 5 cm ringsum \\
Schwellung & Umfang messen oder straff ziehen & Herd, Gelenk \\
Schmerz & Ruhe- und Druckschmerz trennen & Herd, Lymphknoten \\
Funktionseinschränkung & Gelenk bewegen lassen & Glied, Haltung \\
\bottomrule
\end{tabular}
\captionof{table}{Entzündungszeichen und ihre Prüfung (Tab. 4.2)}
\end{center}

\textbf{Schritte: bei Verdacht auf Infektion}
\begin{enumerate}
\item Ruhigstellen des Gliedes, hochlagern über Herzhöhe.
\item Wunde nach Konzept 2.2 spülen und offen lassen (Luft hilft, Fäulnis braucht Verschlossenes).
\item Auflage: Kamillentee-Kompresse, lauwarm, alle 4 Stunden wechseln.
\item Flüssigkeit: 3 Liter über den Tag, falls der Kranke trinkt.
\item Beobachtungsintervall: alle 2 Stunden Rötungsgrenze mit Kugelschreiber am Rand umranden und Zeit notieren.
\item Bei wachsender Umrandung, Fieber über 39 °C oder roten Streifen Richtung Rumpf: jede erreichbare bessere Hilfe, sofort.
\end{enumerate}
\end{konzept}

\section{Wasser ersetzen und Kreislauf stützen}

\begin{konzept}{Konzept 4.3 – Flüssigkeitsersatz beim Kranken}
\textbf{Definition.} Flüssigkeitsersatz gleicht Verluste über Fieber, Durchfall, Erbrechen und Schwitzen aus; das Ziel ist hellgelber Urin alle 4 bis 6 Stunden.

\textbf{Dreifache Prüfung:}
\begin{enumerate}
\item Funktioniert es ohne Strom? Ja – Salz, Zucker, Wasser genügen.
\item Schadet die Regel bei Befolgung nicht? Nein – die Mischung entspricht der oralen Rehydratation der Weltgesundheitsorganisation in ihrer Grundform.
\item Gilt sie gleich in Stadt und Land? Ja.
\end{enumerate}

\textbf{Dreifache Bewertung:}
\begin{enumerate}
\item Einfachheit: hoch – drei Zutaten.
\item Folgenschwere: hoch – Austrocknung tötet Kinder schneller als jede Infektion.
\item Übungsaufwand: gering – Mischung einmal ansetzen und schmecken.
\end{enumerate}

\textbf{Grenzen.} Bei anhaltendem Erbrechen (mehr als 6 Stunden ohne Halten) versagt die orale Gabe; dann zählt jede erreichbare Infusionsmöglichkeit. Prüfe örtlich, ob und wo diese besteht.

\textbf{Trinkplan Fieber (Tab. 4.3)}
\begin{center}
\begin{tabular}{llll}
\toprule
Alter & Grundmenge je Stunde & Fieberzuschlag & Zeichen des Mangels \\
\midrule
Kleinkind & 50 ml & plus 20 ml je Grad & Weinen ohne Tränen, trockene Lippen \\
Kind & 80 ml & plus 30 ml je Grad & Urin dunkler als Stroh \\
Erwachsener & 100 ml & plus 50 ml je Grad & Schwindel beim Aufstehen \\
Alter Mensch & 100 ml & plus 30 ml je Grad & Verwirrtheit, apr Kommunikation \\
\bottomrule
\end{tabular}
\captionof{table}{Trinkplan bei Fieber (Tab. 4.3)}
\end{center}

\textbf{Schritte: Elektrolyttrank ansetzen}
\begin{enumerate}
\item Koche 1 Liter Wasser, 15 Minuten sprudelnd, lass es abkühlen.
\item Löse 6 Teelöffel Zucker und einen halben Teelöffel Salz darin.
\item Schmecke: kaum süß, kaum salzig. Schmeckt es deutlich salzig, ist es zu viel – dann verwerfen und neu mischen.
\item Fülle in eine saubere Flasche, verbrauche binnen 24 Stunden.
\item Gib dem Kranken alle 10 Minuten einen Schluck – nicht große Mengen auf einmal.
\end{enumerate}

\begin{baustein}
\textbf{Merksätze zu Fieber und Infektion.}
\begin{itemize}
\item Fieber ist Abwehr: senke nur ab 39,5 °C, und nie mit kaltem Wasser.
\item Rotgestreifte Bahn zum Rumpf ist ein Lauf zur Hilfe.
\item Kein Urin über 6 Stunden heißt Austrocknung, egal wie der Kranke wirkt.
\item Ein geröteter Wundrand, der wächst, ist umrandet und mit Uhrzeit markiert.
\end{itemize}
\end{baustein}

\begin{stand}
\textbf{Arbeitsstand Fieber.}
\begin{checkliste}
\item Zwei Fieberthermometer vorhanden, eines davon ohne Batterie.
\item Vorlage A.2 liegt am Krankenlager bereit.
\item Elektrolyttrank einmal angesetzt und auf Haltbarkeit 24 Stunden geprüft.
\end{checkliste}
\end{stand}

\section{Kapitel-Checkliste: Fieber und Infektion}
\begin{checkliste}
\item Ich kenne die fünf Stufen der Tab. 4.1 und die zugehörigen Maßnahmen.
\item Ich messe bei Fieber alle 2 Stunden und trage die Werte ein.
\item Ich prüfe die fünf Entzündungszeichen (Tab. 4.2) in dieser Reihenfolge.
\item Ich umrande eine wachsende Rötung mit Uhrzeit und Datum.
\item Ich kenne die Grenze 39,5 °C für aktive Kühlung und kühle nur mit lauwarmem Wasser.
\item Ich kann den Elektrolyttrank aus Wasser, Zucker und Salz ansetzen.
\item Ich erkenne Austrocknung am Urin und an den Lippen, nicht am Bauchgefühl.
\end{checkliste}
