\chapter{Das Krankenlager: das Zimmer als Arznei}

Ein gut geführtes Krankenlager ist selbst ein Heilmittel: Wärme, Sauberkeit, Ruhe und Flüssigkeit heilen mehr Fälle als jede Pflanze dieses Bandes. Das Zimmer wird eingerichtet wie ein Werkzeug – einmal, richtig, mit Prüfraster.

\section{Das Lager einrichten}

\begin{konzept}{Konzept 6.1 – Das Krankenlager einrichten}
\textbf{Definition.} Das Krankenlager ist ein abgetrennter, warmer, sauberer und beobachtbarer Ort mit Bett, Tisch, Wasser und Protokoll – eingerichtet, bevor jemand krank ist.

\textbf{Dreifache Prüfung:}
\begin{enumerate}
\item Braucht es Strom? Nein – Wärmflasche, Kochtopf, Bett, Stoff genügen.
\item Schadet die Einrichtung bei Befolgung nicht? Nein – sie ist für jeden Kranken besser als jedes Sofa.
\item Gilt sie gleich in Stadt und Land? Ja – nur der Raumtyp unterscheidet sich.
\end{enumerate}

\textbf{Dreifache Bewertung:}
\begin{enumerate}
\item Einfachheit: hoch – Einrichtung in einer halben Stunde.
\item Folgenschwere: hoch – Dekubitus (Wundliegen) und Lungenentzündung entstehen aus schlecht gelagert, nicht aus Schicksal.
\item Übungsaufwand: gering.
\end{enumerate}

\textbf{Grenzen.} Ansteckende Fälle (Husten, Durchfall, Ausschlag mit Fieber) gehören in einen Raum mit eigener Tür und eigener Geschirr-, sonst droht Gruppeninfektion (Tab. 6.4).

\textbf{Einrichtungstabelle (Tab. 6.1)}
\begin{center}
\begin{tabular}{lll}
\toprule
Element & Anforderung & Prüfpunkt \\
\midrule
Bett & Trocken, 40 cm über Boden, unterfahrbar für Pflege & Von zwei Seiten erreichbar \\
Lagerung & Zwei Decken, ein wasserdichter Untergrund, Leinentuch & Ohne Falten unter dem Rücken \\
Wärme & Wärmflasche plus zweites Exemplar als Ersatz & Temperatur der Flasche unter 45 °C (Faustwert) \\
Wasser & 10 Liter Trinkwasser am Lager, Geschirr separat & Geschirr nur für den Kranken \\
Beobachtung & Lager so gestellt, dass das Gesicht von der Tür sichtbar ist & Sichtprüfung alle 2 Stunden \\
Protokoll & Vorlage A.1 und A.2 am Kopfende & Einträge vom ersten Krankheitstag \\
\bottomrule
\end{tabular}
\captionof{table}{Checkliste Krankenlager-Einrichtung (Tab. 6.1)}
\end{center}

\textbf{Schritte: Krankenlager einrichten}
\begin{enumerate}
\item Wähle einen Raum mit Tür, Fenster und kurzer Wegstrecke zum Wasser.
\item Räume alles außer Bett, Tisch, Stuhl und Kiste heraus.
\lineitem Lege die Liegefläche: Schaumstoff oder gefaltete Decken, 8 bis 10 cm dick, darüber wasserdichte Schicht, darüber Leinentuch.
\item Stelle Trinkwasser, Geschirr, Waschschüssel, Wärmflasche und Protokolle ans Kopfende.
\item Kennzeichne die Tür: Name des Kranken, Datum des Beginns, ansteckend oder nicht.
\item Vereinbare mit der Gruppe das Beobachtungsraster (Tab. 6.2).
\end{enumerate}

\textbf{Stadt und Land: Raumwahl (Tab. 6.2)}
\begin{center}
\begin{tabular}{lll}
\toprule
 & Stadt & Land \\
\midrule
Typischer Raum & Zimmer zur Hofseite, vom Lärm abgewandt & Nebenkammer oder separater Anbau \\
Wärmequelle & Nachbarglied des Schornsteins, Wärmflaschen & Kachelofen, Warmsteine in Tüchern \\
Gefahr des Raums & Zugluft, Feuchtigkeit in Neubauten & Stallgeruch, Zug über Türspalt \\
Prüfpunkt & Feuchtewand am Morgen prüfen & Boden auf Zug mit Kerze testen \\
\bottomrule
\end{tabular}
\captionof{table}: Raumwahl für das Krankenlager (Tab. 6.2)}
\end{center}
\end{konzept}

\section{Pflegeroutine und Lagerungswechsel}

\begin{konzept}{Konzept 6.2 – Pflegetag und Lagerungswechsel}
\textbf{Definition.} Der Pflegetag ist ein festes Raster aus Waschen, Essen, Trinken, Lagewechsel und Beobachtung; der Lagewechsel verhindert Wundliegen, indem er Druckstellen wechselt, bevor die Haut stirbt.

\textbf{Dreifache Prüfung:}
\begin{enumerate}
\item Funktioniert das Raster ohne Apparate? Ja – Wecker oder Tageslicht genügen als Takt.
\item Schadet es bei Befolgung nicht? Nein – die Zeiten sind auf das Minimum gestellt.
\item Gilt es gleich in Stadt und Land? Ja.
\end{enumerate}

\textbf{Dreifache Bewertung:}
\begin{enumerate}
\item Einfachheit: hoch.
\item Folgenschwere: hoch – Wundliegen beginnt nach 6 Stunden konstanten Drucks und ist nicht heilbar, nur verhinderbar.
\item Übungsaufwand: mittel – der Lagewechsel braucht zwei geübte Hände.
\end{enumerate}

\textbf{Grenzen.} Wer nicht dreht, wund liegt: Der Wechsel ist bei Bewusstlosen und sehr Schwachen eine Pflicht, keine Empfehlung.

\textbf{Das Tagesraster (Tab. 6.3)}
\begin{center}
\begin{tabular}{lll}
\toprule
Uhrzeit (Tageslicht) & Aufgabe & Eintrag \\
\midrule
Morgens & Waschen, Wäsche, Fiebermessen & A.1 und A.2 \\
Alle 2 Stunden & Lagewechsel, Getränk reichen & A.1 \\
Mittags & Kost nach Stufenplan (Tab. 5.3 oder Normal) & A.1 \\
Nachmittags & Lagewechsel, Haut an Fersen, Kreuz, Ellbogen prüfen & A.1 \\
Abends & Waschen, Protokoll abschließen, Übergabe an Nachtpflege & A.1 \\
Nachts & Alle 4 Stunden Umlagerung und Trinken & A.1 \\
\bottomrule
\end{tabular}
\captionof{table}{Pflegetag-Raster (Tab. 6.3)}
\end{center}

\textbf{Schritte: Lagewechsel beim liegenden Kranken}
\begin{enumerate}
\item Wasche deine Hände 30 Sekunden mit Seife.
\item Kläre die Bewegung mit dem Kranken, wenn er wach ist.
\item Stelle den Kranken quer im Bett, knie an einer Seite, eine Hand unter die Schulter, eine unter die Hüfte.
\item Ziehe in einer Bewegung auf die Seite, Beine leicht angewinkelt, oberes Knie auf ein Polster.
\item Prüfe die Druckstellen: Fersen, Kreuz, Ellbogen, Ohren – rot gebliebene Stellen umkreisen und eintragen.
\item Lasse die Lage 2 Stunden, dann wechsle die Seite oder in Rückenlage mit Kissen unter den Waden.
\end{enumerate}

\section{Ausscheidung und Hygiene}

\begin{konzept}{Konzept 6.3 – Ausscheidung hygienisch führen}
\textbf{Definition.} Ausscheidungspflege heißt, Urin und Stuhl so aufzufangen und zu entsorgen, dass weder der Kranke noch die Pflege keimbelastet werden.

\textbf{Dreifache Prüfung:}
\begin{enumerate}
\item Braucht es Fertigprodukte? Nein – Eimer, Deckel, Sägemehl oder Erde genügen.
\item Schadet die Regel bei Befolgung nicht? Nein – sie trennt gefährliche von harmloser Arbeit.
\item Gilt sie gleich in Stadt und Land? Ja – nur das Entsorgungsende unterscheidet sich.
\end{enumerate}

\textbf{Dreifache Bewertung:}
\begin{enumerate}
\item Einfachheit: hoch – Eimer, Deckel, Zeitplan.
\item Folgenschwere: hoch – Fäkalien im Wohnbereich sind der häufigste Ausbruchspunkt von Ruhr.
\item Übungsaufwand: gering.
\end{enumerate}

\textbf{Grenzen.} Ohne funktionierende Abwasseranschlüsse endet jede Entsorgung im Boden: Grube mit 60 cm Erddeckel, 30 m von Brunnen entfernt (Faustwert, örtlich prüfen).

\textbf{Hygieneregeln am Lager (Tab. 6.4)}
\begin{center}
\begin{tabular}{lll}
\toprule
Bereich & Regel & Instrument \\
\midrule
Hände & 30 Sekunden Seife nach jedem Kontakt & Seife, Wasser, Fingernagelbürste \\
Geschirr & Nur für den Kranken, abkochen 5 Minuten & Eigener Topf \\
Leibwäsche & Täglich wechseln, getrennt waschen, kochen & Eigener Waschkessel \\
Ausscheidung & Eimer mit Deckel, Deckelerde, zweimal täglich ab & Eimer, Säge­späne \\
Raum & Einmal täglich lüften 10 Minuten, Böden feucht wischen & Essigwasser (Tab. 8.3) \\
\bottomrule
\end{tabular}
\captionof{table}{Hygieneraster am Krankenlager (Tab. 6.4)}
\end{center}

\textbf{Schritte: Steckbecken führen}
\begin{enumerate}
\item Decke das Steckbecken mit einer dünnen Säge­späne-Schicht aus.
\item Reiche es diskret, warte außer Hörweite.
\item Entleere es in die Grube nach Konzept 6.3-Grenze, nie in offene Gräben.
\item Reinige es mit Wasser und Bürste, koche es 5 Minuten ab, stelle es getrocknet unter das Bett.
\item Wasche deine Hände nach jedem Schritt, auch nach dem Deckelaufheben.
\end{enumerate}

\begin{figure}[ht]
\centering
\includesvg[width=\textwidth]{illustrationen/abb-6-1}
\caption{Abb. 6.1 – Der Lagewechsel: Druckstellen wechseln, bevor die Haut stirbt}
\end{figure}

\begin{baustein}
\textbf{Merksätze zum Krankenlager.}
\begin{itemize}
\item Wärme, Wasser, Wäsche, Wenden – die vier W sind die Hälfte der Heilkunde.
\item Rote Stelle drückt nicht mehr, wenn sie umkreist ist: Eintrag genügt nicht – Umlagerung folgt sofort.
\item Geschirr des Kranken bleibt Geschirr des Kranken.
\item Das Protokoll ist die Übergabe: Was nicht steht, geschieht in der Nacht nicht.
\end{itemize}
\end{baustein}

\begin{stand}
\textbf{Arbeitsstand Krankenlager.}
\begin{checkliste}
\item Ein Raum als Krankenlager gewählt, eingerichtet und mit Prüfpunkten versehen.
\item Zwei Wärmflaschen vorhanden, eine als Reserve geprüft.
\item Hygieneraster Tab. 6.4 als Zettel am Raum aufgehängt.
\end{checkliste}
\end{stand}

\section{Kapitel-Checkliste: Das Krankenlager}
\begin{checkliste}
\item Ich habe ein Zimmer als Krankenlager gewählt und nach Tab. 6.1 eingerichtet.
\item Ich kann den Lagewechsel allein und zu zweit in unter 2 Minuten ausführen.
