  const fs: any = (globalThis as any).fs;
  const files = ["abb-2-1","abb-3-1","abb-4-1","abb-6-1","abb-7-1","abb-8-1","abb-9-1"];
  const base = "/home/user/baende/band-08/illustrationen/";
  const report: string[] = [];
  for (const f of files) {
    let text = "";
    try { text = fs.readFileSync(base + f + ".svg", "utf8"); } catch { report.push(f + ": READ FAILED"); continue; }
    const vb = /viewBox="0 0 (\d+) (\d+)"/.exec(text);
    const W = vb ? +vb[1] : 760, H = vb ? +vb[2] : 0;
    const boxes: any[] = [];
    const re = /<text x="(\d+)" y="(\d+)" font-size="(\d+)"([^>]*)>([^<]*)<\/text>/g;
    let m: any;
    while ((m = re.exec(text))) {
      const x = +m[1], y = +m[2], fs2 = +m[3], attrs = m[4], content = m[5];
      const middle = attrs.includes('text-anchor="middle"');
      const w = content.length * 0.62 * fs2;
      const h = fs2 * 1.25;
      const left = middle ? x - w/2 : x;
      const top = y - fs2 * 0.8;
      boxes.push({content, x, y, fs: fs2, w, left, right: left + w, top, bottom: top + h, middle});
    }
    const probs: string[] = [];
    for (const b of boxes) {
      if (b.left < 8) probs.push(`RAND-L "${b.content}" left=${b.left.toFixed(1)}`);
      if (b.right > W - 8) probs.push(`RAND-R "${b.content}" right=${b.right.toFixed(1)} W=${W}`);
      if (b.top < 8) probs.push(`RAND-O "${b.content}"`);
      if (b.bottom > H - 8) probs.push(`RAND-U "${b.content}" bottom=${b.bottom.toFixed(1)} H=${H}`);
      if (b.content.trim() === "") probs.push(`LEER @${b.x},${b.y}`);
    }
    for (let i = 0; i < boxes.length; i++) for (let j = i+1; j < boxes.length; j++) {
      const a = boxes[i], b = boxes[j];
      if (a.left < b.right && b.left < a.right && a.top < b.bottom && b.top < a.bottom)
        probs.push(`KOLLISION "${a.content}" vs "${b.content}"`);
    }
    report.push(`### ${f}.svg — ${boxes.length} Labels, viewBox 0 0 ${W} ${H}`);
    for (const b of boxes) report.push(`  "${b.content}" fs=${b.fs} Breite≈${b.w.toFixed(0)}px x=${b.x} y=${b.y} links=${b.left.toFixed(0)} rechts=${b.right.toFixed(0)}`);
    report.push(probs.length ? "  PROBLEME: " + probs.join(" | ") : "  OK: Rand ≥ 8 px, keine Kollision, kein leeres Element");
  }
  return report.join("\n");
}
main();

